// --- CLEAN SUBJECT - SUBWORKFLOW - SINGLE INPUT `$input.item` ---
const subject = $input.item.json.subject || "";

function cleanSubject(subject) {
  if (!subject) return "";

  // Supprime "Subject: " au début
  subject = subject.replace(/^Subject:\s*/i, "");

  // Décode les caractères encodés en quoted-printable (=?UTF-8?Q?...)
  subject = subject.replace(/=\?UTF-8\?Q\?([^?]+)\?=/gi, (match, encoded) => {
    return encoded
      .replace(/=([0-9A-F]{2})/g, (m, hex) => String.fromCharCode(parseInt(hex, 16)))
      .replace(/_/g, " ");
  });

  // Décode les caractères encodés en base64 (=?UTF-8?B?...)
  subject = subject.replace(/=\?UTF-8\?B\?([^?]+)\?=/gi, (match, encoded) => {
    return Buffer.from(encoded, 'base64').toString('utf-8');
  });

  // Supprime les retours à la ligne et espaces multiples
  subject = subject
    .replace(/\r?\n/g, "")
    .replace(/\s{2,}/g, " ")
    .trim();

  return subject;
}

return {
  json: {
    cleanSubject: cleanSubject(subject)
  }
};

